import zipfile
import xml.etree.ElementTree as ET

NS = {
    "main": "http://schemas.openxmlformats.org/spreadsheetml/2006/main",
    "rel": "http://schemas.openxmlformats.org/officeDocument/2006/relationships",
    "pkgrel": "http://schemas.openxmlformats.org/package/2006/relationships",
}

def col_to_idx(ref):
    letters = ""
    for ch in ref:
        if ch.isalpha():
            letters += ch
        else:
            break
    idx = 0
    for ch in letters:
        idx = idx * 26 + (ord(ch.upper()) - ord("A") + 1)
    return idx

def col_to_letters(idx):
    letters = ""
    while idx > 0:
        idx, rem = divmod(idx - 1, 26)
        letters = chr(ord("A") + rem) + letters
    return letters

with zipfile.ZipFile("budget.xlsx") as z:
    names = z.namelist()
    print("Archive members:")
    for n in names:
        print("  ", n)

    # shared strings
    shared = []
    if "xl/sharedStrings.xml" in names:
        root = ET.fromstring(z.read("xl/sharedStrings.xml"))
        for si in root.findall("main:si", NS):
            text = "".join(t.text or "" for t in si.iter() if t.tag.endswith("}t"))
            shared.append(text)
    print("\nShared strings count:", len(shared))

    # workbook sheet list
    wb_root = ET.fromstring(z.read("xl/workbook.xml"))
    sheet_names = []
    for sh in wb_root.find("main:sheets", NS):
        sheet_names.append(sh.get("name"))
    print("Sheet names:", sheet_names)

    # worksheet files via workbook.xml.rels
    rel_root = ET.fromstring(z.read("xl/_rels/workbook.xml.rels"))
    rels = {}
    for rel in rel_root:
        rid = rel.get("Id")
        target = rel.get("Target")
        if target.startswith("/"):
            target = target[1:]
        else:
            target = "xl/" + target
        rels[rid] = target

    for sh in wb_root.find("main:sheets", NS):
        rid = sh.get("{http://schemas.openxmlformats.org/officeDocument/2006/relationships}id")
        target = rels.get(rid)
        print(f"\n=== Sheet: {sh.get('name')} -> {target} ===")
        ws_root = ET.fromstring(z.read(target))
        sd = ws_root.find("main:sheetData", NS)
        if sd is None:
            print("(empty)")
            continue
        for row in sd.findall("main:row", NS):
            r = row.get("r")
            cells = []
            for c in row.findall("main:c", NS):
                ref = c.get("r")
                t = c.get("t")
                v = c.find("main:v", NS)
                isel = c.find("main:is", NS)
                raw = None
                if t == "s" and v is not None:
                    raw = shared[int(v.text)]
                elif t == "inlineStr" and isel is not None:
                    raw = "".join(tt.text or "" for tt in isel.iter() if tt.tag.endswith("}t"))
                elif t == "str" and v is not None:
                    raw = v.text
                elif v is not None:
                    raw = v.text
                cells.append((ref, raw))
            print(r, cells)

